def predict(features: np.ndarray, label: str) -> np.ndarray:
    data = MODEL_DATA[label]
    children_left = np.asarray(data["children_left"], dtype=np.int32)
    children_right = np.asarray(data["children_right"], dtype=np.int32)
    split_features = np.asarray(data["feature"], dtype=np.int32)
    thresholds = np.asarray(data["threshold"], dtype=float)
    leaf_class = np.asarray(data["leaf_class"], dtype=bool)
    result = np.zeros(len(features), dtype=bool)
    for row_index, row in enumerate(features):
        node = 0
        while children_left[node] != -1:
            node = children_left[node] if row[split_features[node]] <= thresholds[node] else children_right[node]
        result[row_index] = leaf_class[node]
    return result
